import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('useEffect & Lifecycle', () => {
  test('Renders count as 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el) throw new Error('No #count element');
if (!el.textContent.includes('0')) throw new Error('Initial count should be 0');
  });

  test('document.title updates with count', async () => {
    const { container: root } = render(<App />);
    if (!document.title.includes('Count:')) throw new Error('document.title should contain "Count:"');
const btn = root.querySelector('#increment');
btn.click();
await tick();
if (!document.title.includes('1')) throw new Error('document.title should contain "1" after increment');
  });

  test('Shows "Component is mounted!" on mount', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#mounted');
if (!el) throw new Error('No #mounted element');
if (!el.textContent.includes('Component is mounted!'))
  throw new Error('Should display "Component is mounted!"');
  });

  test('Increment button updates count', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#increment');
if (!btn) throw new Error('No #increment button');
btn.click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('2')) throw new Error('Count should update on click');
  });
});
